def _cart_position(event, item, membership=None, **kwargs):
    return CartPosition(
        event=event, item=item, price=23, expires=now() + timedelta(days=1), cart_id="123",
        used_membership=membership, **kwargs
    )


def _paid_order_with_membership(event, customer, item, membership, **kwargs):
    order = Order.objects.create(
        event=event, email='dummy@example.org', status=Order.STATUS_PAID, datetime=now(),
        expires=now() + timedelta(days=10), total=Decimal('23.00'), testmode=membership.testmode,
        sales_channel=event.organizer.sales_channels.get(identifier="web"), customer=customer,
    )
    OrderPosition.objects.create(
        order=order, item=item, price=Decimal('23.00'), used_membership=membership, **kwargs
    )
    return order


@pytest.mark.django_db
def test_membership_validation_ignores_positions_not_requiring_membership(event, granting_ticket):
    validate_memberships_in_order(None, [_cart_position(event, granting_ticket)], event)


@pytest.mark.django_db
def test_membership_validation_accepts_valid_membership(event, customer, membership, requiring_ticket):
    validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event)


@pytest.mark.django_db
def test_membership_validation_accepts_membership_with_lock(event, customer, membership, requiring_ticket):
    validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event, lock=True)


@pytest.mark.django_db
def test_membership_validation_rejects_missing_customer(event, requiring_ticket, membership):
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(None, [_cart_position(event, requiring_ticket, membership)], event)
    assert 'membership' in excinfo.value.message


@pytest.mark.django_db
def test_membership_validation_rejects_missing_selection(event, customer, requiring_ticket):
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket)], event)
    assert 'membership' in excinfo.value.message


@pytest.mark.django_db
def test_membership_validation_rejects_membership_of_other_customer(event, customer, membership, requiring_ticket):
    other = event.organizer.customers.create(email="jane@example.org")
    own = other.memberships.create(
        membership_type=membership.membership_type,
        date_start=membership.date_start,
        date_end=membership.date_end,
    )
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, own)], event)
    assert 'membership' in excinfo.value.message


@pytest.mark.django_db
def test_membership_validation_rejects_canceled_membership(event, customer, membership, requiring_ticket):
    membership.canceled = True
    membership.save()
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event)
    assert 'membership' in excinfo.value.message


@pytest.mark.django_db
def test_membership_validation_rejects_testmode_mismatch(event, customer, membership, requiring_ticket):
    membership.testmode = True
    membership.save()
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event)
    validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event, testmode=True)


@pytest.mark.django_db
def test_membership_validation_rejects_membership_type_not_required(event, customer, membership, requiring_ticket):
    other_type = event.organizer.membership_types.create(name="Half pass")
    half = customer.memberships.create(
        membership_type=other_type,
        date_start=membership.date_start,
        date_end=membership.date_end,
    )
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, half)], event)
    assert 'membership' in excinfo.value.message


@pytest.mark.django_db
def test_membership_validation_rejects_expired_membership(event, customer, membership, requiring_ticket):
    membership.date_start = datetime(2021, 1, 1, 0, 0, 0, 0, tzinfo=TZ)
    membership.date_end = datetime(2021, 2, 28, 23, 59, 59, 999999, tzinfo=TZ)
    membership.save()
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event)
    assert 'membership' in excinfo.value.message


@pytest.mark.django_db
def test_membership_validation_valid_from_not_chosen_only_checks_expiry(event, customer, membership, requiring_ticket):
    membership.date_start = datetime(2030, 1, 1, 0, 0, 0, 0, tzinfo=TZ)
    membership.date_end = datetime(2030, 12, 31, 23, 59, 59, 999999, tzinfo=TZ)
    membership.save()
    position = _cart_position(event, requiring_ticket, membership)
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [position], event)
    validate_memberships_in_order(customer, [position], event, valid_from_not_chosen=True)


@pytest.mark.django_db
def test_membership_validation_rejects_exceeded_max_usages(event, customer, membership, requiring_ticket):
    membership.membership_type.max_usages = 1
    membership.membership_type.save()
    positions = [
        _cart_position(event, requiring_ticket, membership),
        _cart_position(event, requiring_ticket, membership),
    ]
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, positions, event, testmode=False)
    assert 'membership' in excinfo.value.message


@pytest.mark.django_db
def test_membership_validation_counts_existing_usages_except_ignored_order(event, customer, membership, requiring_ticket):
    membership.membership_type.max_usages = 1
    membership.membership_type.save()
    order = _paid_order_with_membership(event, customer, requiring_ticket, membership)
    position = _cart_position(event, requiring_ticket, membership)
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [position], event)
    validate_memberships_in_order(customer, [position], event, ignored_order=order)


@pytest.mark.django_db
def test_membership_validation_rejects_parallel_usage_for_same_event(event, customer, membership, requiring_ticket):
    positions = [
        _cart_position(event, requiring_ticket, membership),
        _cart_position(event, requiring_ticket, membership),
    ]
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, positions, event)
    assert 'membership' in excinfo.value.message


@pytest.mark.django_db
def test_membership_validation_allows_parallel_usage_if_configured(event, customer, membership, requiring_ticket):
    membership.membership_type.allow_parallel_usage = True
    membership.membership_type.save()
    positions = [
        _cart_position(event, requiring_ticket, membership),
        _cart_position(event, requiring_ticket, membership),
    ]
    validate_memberships_in_order(customer, positions, event)


@pytest.mark.django_db
def test_membership_validation_rejects_existing_usage_for_same_event(event, customer, membership, requiring_ticket):
    order = _paid_order_with_membership(event, customer, requiring_ticket, membership)
    position = _cart_position(event, requiring_ticket, membership)
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [position], event)
    assert 'membership' in excinfo.value.message
    validate_memberships_in_order(customer, [position], event, ignored_order=order)


@pytest.mark.django_db
def test_membership_validation_ignores_canceled_existing_usage(event, customer, membership, requiring_ticket):
    order = _paid_order_with_membership(event, customer, requiring_ticket, membership)
    order.status = Order.STATUS_CANCELED
    order.save()
    position = _cart_position(event, requiring_ticket, membership)
    validate_memberships_in_order(customer, [position], event)
